    private static final class Node {
        final List<ModelPart.Cube> cubes = new ArrayList<>();
        final Map<String, Node> children = new LinkedHashMap<>();
        PartPose pose = PartPose.ZERO;
        ModelPart bake() {
            Map<String, ModelPart> parts = new LinkedHashMap<>();
            children.forEach((name, node) -> parts.put(name, node.bake()));
            var result = new ModelPart(List.copyOf(cubes), parts);
            result.setInitialPose(pose); result.loadPose(pose);
            return result;
        }
    }
    private static Node part(Node parent, String name, float x, float y, float z, float rx, float ry, float rz) {
        var node = new Node(); node.pose = PartPose.offsetAndRotation(x,y,z,rx,ry,rz);
        parent.children.put(name,node); return node;
    }
    private static void cube(Node node, float x, float y, float z, float dx, float dy, float dz, float inflate, float[][] uv) {
        node.cubes.add(new UvCube(x,y,z,dx,dy,dz,inflate,uv));
    }
    /** Vanilla cube geometry with exact author UVs, including fractional-sized cuboids.
     * Vanilla's box-UV constructor recomputes UV widths from geometric dimensions;
     * that would shift this model's hand-painted atlas. No reflection or mixin needed. */
    private static final class UvCube extends ModelPart.Cube {
        private static final int[][] CORNERS = {{5,4,0,1},{2,3,7,6},{0,4,7,3},{1,0,3,2},{5,1,2,6},{4,5,6,7}};
        private static final Direction[] NORMALS = {Direction.DOWN,Direction.UP,Direction.WEST,Direction.NORTH,Direction.EAST,Direction.SOUTH};
        private final float[][] positions;
        private final float[][] uv;
        UvCube(float x,float y,float z,float dx,float dy,float dz,float inflate,float[][] uv) {
            super(0,0,x,y,z,dx,dy,dz,0,0,0,false,128,128,Set.of());
            float a=x-inflate,b=y-inflate,c=z-inflate,d=x+dx+inflate,e=y+dy+inflate,f=z+dz+inflate;
            positions=new float[][]{{a,b,c},{d,b,c},{d,e,c},{a,e,c},{a,b,f},{d,b,f},{d,e,f},{a,e,f}};
            this.uv=uv;
        }
        @Override public void compile(PoseStack.Pose pose,VertexConsumer consumer,int light,int overlay,int color) {
            var normal=new Vector3f(); var vertex=new Vector3f();
            for(int face=0;face<6;face++) {
                float[] rect=uv[face]; if(rect==null)continue;
                Direction n=NORMALS[face];
                pose.transformNormal(normal.set(n.getStepX(),n.getStepY(),n.getStepZ()),normal);
                for(int corner=0;corner<4;corner++) {
                    float[] p=positions[CORNERS[face][corner]];
                    pose.pose().transformPosition(p[0]/16,p[1]/16,p[2]/16,vertex);
                    float u=(corner==0||corner==3?rect[2]:rect[0])/128;
                    float v=(corner<2?rect[1]:rect[3])/128;
                    consumer.addVertex(vertex.x,vertex.y,vertex.z,color,u,v,overlay,light,normal.x,normal.y,normal.z);
                }
            }
        }
    }
    private VaultHunterGeometry() {}
